import{_ as a,o as t,c as r,a4 as l}from"./chunks/framework.ClGzHnIj.js";const m=JSON.parse('{"title":"Carte du GPU","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/gpu-map.html"}]]},"headers":[],"relativePath":"fr/guide/gpu-map.md","filePath":"fr/guide/gpu-map.md","lastUpdated":1792799313000}'),s={name:"fr/guide/gpu-map.md"};function o(i,e,n,u,c,d){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="carte-du-gpu" tabindex="-1">Carte du GPU <a class="header-anchor" href="#carte-du-gpu" aria-label="Permalink to &quot;Carte du GPU&quot;">​</a></h1><p>La <strong>Carte du GPU</strong> montre ce qui occupe la mémoire vidéo en ce moment, modèle par modèle, ce que le contexte de chacun coûte en plus de ses poids, ce qui est libre, et lesquels de vos autres modèles tiendraient encore.</p><p><strong>Élément de la barre latérale :</strong> Carte du GPU (sous Machine partagée) <strong>Route :</strong> <code>/gpu</code><strong>Ajouté dans :</strong> v0.8.0 (octobre 2026) <strong>Nécessite :</strong> rien de plus. Elle lit toutes les quelques secondes ce qu&#39;Ollama annonce des modèles chargés. La taille de la mémoire de la carte vient du pilote NVIDIA sur Windows et Linux, et du système sur macOS.</p><h2 id="a-quoi-ca-sert" tabindex="-1">À quoi ça sert ? <a class="header-anchor" href="#a-quoi-ca-sert" aria-label="Permalink to &quot;À quoi ça sert ?&quot;">​</a></h2><p>« Est-ce que ça tient ? » est la question de chaque discussion sur les modèles locaux, et la réponse est souvent un chiffre de <code>nvidia-smi</code> que personne ne sait lire. La carte le dessine.</p><h2 id="la-barre" tabindex="-1">La barre <a class="header-anchor" href="#la-barre" aria-label="Permalink to &quot;La barre&quot;">​</a></h2><p>Une barre, de la largeur de la mémoire vidéo de la carte. Un bloc par modèle chargé, coupé en deux : les poids, et, plus pâle, ce que le contexte et les tampons de travail coûtent en plus. Puis l&#39;espace libre. Survolez un bloc pour sa taille.</p><p>Sous la barre, chaque modèle chargé avec sa taille, sa quantification, le contexte avec lequel il est chargé, et le moment où le démon le déchargera s&#39;il ne sert plus. Un modèle qui n&#39;a pas tenu montre la part qui tourne depuis la RAM système, ce qui explique sa lenteur.</p><h2 id="quand-le-chiffre-d-ollama-ne-peut-pas-etre-vrai" tabindex="-1">Quand le chiffre d&#39;Ollama ne peut pas être vrai <a class="header-anchor" href="#quand-le-chiffre-d-ollama-ne-peut-pas-etre-vrai" aria-label="Permalink to &quot;Quand le chiffre d&#39;Ollama ne peut pas être vrai&quot;">​</a></h2><p>Ollama 0.40.6 à 0.40.10 sous-estiment la mémoire sur son moteur llama.cpp : il peut annoncer 432 Mo pour un gemma4 dont le fichier fait 6,1 Go, alors que la carte en contient 9 (<a href="https://github.com/ollama/ollama/issues/19089" target="_blank" rel="noreferrer">ollama#19089</a>). Un modèle chargé ne peut pas occuper moins que son propre fichier ; quand Ollama annonce moins de la moitié de ce fichier, la carte ne dessine pas ce chiffre. Elle utilise la taille du fichier à la place, le dit sous le modèle avec ce qu&#39;Ollama a annoncé, et laisse de côté la part du contexte, qui n&#39;est pas connue. Les verdicts ci-dessous sont jugés sur le chiffre corrigé. Les outils MCP <code>list_local_models</code> et <code>estimate_my_prompt</code> ajoutent la même phrase pour les agents.</p><h2 id="ce-qui-tiendrait-encore" tabindex="-1">Ce qui tiendrait encore <a class="header-anchor" href="#ce-qui-tiendrait-encore" aria-label="Permalink to &quot;Ce qui tiendrait encore&quot;">​</a></h2><p>Chaque modèle téléchargé qui n&#39;est pas chargé, face à l&#39;espace libre, avec l&#39;un de trois verdicts :</p><ul><li><strong>tient maintenant</strong>, à côté de ce qui est chargé ;</li><li><strong>tient seulement si ce qui est chargé est d&#39;abord déchargé</strong> ;</li><li><strong>plus grand que cette carte</strong> : il tournerait en partie depuis la RAM système.</li></ul><p>Un modèle a besoin d&#39;environ 15 % de plus que son fichier pour un contexte modeste ; les verdicts en tiennent compte.</p><h2 id="ce-que-la-page-ne-sait-pas" tabindex="-1">Ce que la page ne sait pas <a class="header-anchor" href="#ce-que-la-page-ne-sait-pas" aria-label="Permalink to &quot;Ce que la page ne sait pas&quot;">​</a></h2><p>Comment le démon répartit l&#39;empreinte d&#39;un modèle entre les poids et le contexte. Les poids sont le fichier sur disque ; le reste est le cache du contexte et les tampons de travail, donc cette répartition est une estimation. L&#39;espace libre est la mémoire de la carte moins ce qu&#39;Ollama annonce comme chargé ; les autres programmes qui utilisent le GPU ne sont pas comptés.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./system.html">Mon système</a> pour la carte et le pilote.</li><li><a href="./shared-box.html">Machine partagée</a> pour savoir quel outil a réservé le contexte.</li></ul>',18)])])}const h=a(s,[["render",o]]);export{m as __pageData,h as default};
